import type { TroubleCodeGuide } from "./trouble-code-data";

const manuals={label:"Toyota Tacoma manuals and warranty guides",url:"https://www.toyota.com/owners/warranty-owners-manuals/",note:"Official Toyota model-year document lookup; use VIN-, engine- and drivetrain-correct Toyota repair information"};
const catalyst2010={label:"Toyota T-SB-0161-13 — 2010 Tacoma 2TR-FE P0420/catalyst rattle",url:"https://static.nhtsa.gov/odi/tsbs/2013/MC-10132102-9999.pdf",note:"2010 Tacoma 2TR-FE only; requires the listed front-catalyst rattle inspection before exhaust-pipe replacement"};
const valveRecall={label:"Toyota Safety Recall D0U — 2013–2014 Tacoma 2TR-FE valve springs",url:"https://static.nhtsa.gov/odi/rcl/2013/RCMN-13V557-5284.pdf",note:"Certain VIN-identified 2013–2014 four-cylinder Tacomas; pitted valve springs may break and cause noise, rough running or engine stoppage"};

const vehicle={name:"Toyota Tacoma",kicker:"TOYOTA TACOMA · ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Toyota Tacoma",about:"Toyota Tacoma engine and emissions diagnostics",yearsIntro:"Tacoma diagnostics span older 2RZ/3RZ and 5VZ engines, the long-running 2TR-FE four-cylinder and 1GR-FE V6, 2016–2023 2GR-FKS V6, and 2024+ turbocharged T24A-FTS including i-FORCE MAX. Engine, bank layout, fuel system, EVAP routing, VVT strategy and bulletin coverage differ. Confirm model year, VIN, engine code, drivetrain and emissions label before choosing tests."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle">&{slug:string};
const article=(x:Input):TroubleCodeGuide=>({...x,slug:`toyota/tacoma/${x.slug}`,vehicle});

export const troubleCodeTacoma:TroubleCodeGuide[]=[
article({slug:"p0420",code:"P0420",title:"P0420 Code Toyota Tacoma: Catalyst Tests and 2TR-FE Bulletin",description:"Diagnose Tacoma P0420 by checking misfire, trims, oil use, exhaust leaks and sensors, plus exact 2010 2TR-FE catalyst-rattle bulletin limits.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",severity:"Service soon",driveAdvice:"P0420 alone with normal operation usually permits a short diagnostic trip. Stop for a flashing misfire lamp, raw-fuel odor, an exhaust component glowing hot, severe rattling or power loss that suggests restriction. Towing or climbing with an active misfire can overheat the catalyst rapidly.",quickAnswer:"P0420 means the ECM judged Bank 1 catalyst oxygen-storage performance below threshold. It does not identify what damaged the catalyst. Repair misfire and fuel-trim faults, check oil/coolant consumption, inspect the Bank 1 exhaust for leaks and verify A/F and downstream oxygen-sensor response before condemning the converter. Toyota T-SB-0161-13 adds a narrow repair branch for a 2010 Tacoma 2TR-FE with catalyst-section rattle; it is not a universal Tacoma converter bulletin.",symptoms:[{key:"normal",label:"Lamp on, truck drives normally",response:"Preserve readiness and freeze frame; test catalyst prerequisites before parts."},{key:"rattle",label:"Rattle from the front catalyst",response:"On a matched 2010 2TR-FE, follow the heat-safe localization in T-SB-0161-13."},{key:"flash",label:"Lamp flashes under tow/load",response:"Release load and stop sustained driving; repair the misfire first."},{key:"power",label:"Power falls at higher rpm",response:"Test exhaust restriction and inspect for broken substrate."},{key:"repeat",label:"Code returned after converter work",response:"Audit emissions application, upstream faults, leaks and sensor circuits."}],causes:[{cause:"Catalyst storage capacity depleted or substrate damaged",evidence:"Prerequisites pass and Toyota test fails",firstTest:"Engine/emissions-specific catalyst evaluation"},{cause:"Misfire or rich/lean operation damaged catalyst",evidence:"Historical codes, abnormal trims or deposits",firstTest:"Correct ignition/fuel root cause before catalyst testing"},{cause:"Oil or coolant contamination",evidence:"Consumption, smoke, coolant loss or deposits",firstTest:"Mechanical and cooling-system diagnosis"},{cause:"Exhaust leak around Bank 1 sensors/catalyst",evidence:"Cold tick, soot or leak-test evidence",firstTest:"Inspect cold and leak-test safely"},{cause:"A/F or downstream O2 sensor/circuit fault",evidence:"Controlled response or circuit test fails",firstTest:"Graph both sensors and test wiring"}],freezeFrame:["RPM, calculated load, speed and coolant temperature","Fuel trims and misfire history","Upstream A/F and downstream O2 data","Oil/coolant consumption and towing history","Exhaust rattle/restriction evidence","Engine code and emissions certification"],steps:[{title:"Save codes and readiness",detail:"Keep the monitor context before clearing."},{title:"Resolve upstream faults",detail:"Repair misfire, mixture and sensor circuit codes first."},{title:"Inspect leaks and contamination",detail:"Check Bank 1 exhaust, oil use and coolant loss."},{title:"Graph sensor response",detail:"Use the exact engine's Toyota test conditions."},{title:"Test catalyst storage/restriction",detail:"Apply T-SB-0161-13 only to its exact 2010 2TR-FE case."},{title:"Complete the monitor",detail:"Verify no pending P0420 under safe enable conditions."}],dontReplace:"Do not replace a converter or downstream sensor from one P0420. T-SB-0161-13 requires a 2010 2TR-FE and a localized front-catalyst rattle; similar code wording on another Tacoma does not extend that repair.",yearNotes:["T-SB-0161-13 specifically lists 2010 Tacoma with 2TR-FE and directs a rattle check at the front exhaust-pipe catalyst.","A four-cylinder has only Bank 1; V6 engines have two banks, so P0420 and P0430 refer to different exhaust paths.","Federal/California certification and wheelbase/drivetrain can affect exhaust part application.","Towing load can expose misfire, rich operation and restriction that are not obvious at idle."],faqs:[{question:"Does P0420 always mean a bad converter?",answer:"No. Upstream engine, exhaust leak and sensor faults must be excluded."},{question:"Does the Toyota rattle bulletin cover every Tacoma?",answer:"No. It names a narrow 2010 2TR-FE application."},{question:"Which side is Bank 1?",answer:"It contains cylinder 1; confirm the exact V6 engine diagram. A four-cylinder has one bank."},{question:"Can I tow with P0420?",answer:"Avoid heavy load until misfire and restriction are excluded."},{question:"Can oil burning cause it?",answer:"Yes, oil contamination can reduce catalyst activity."},{question:"Will cleaner repair it?",answer:"No additive restores melted or depleted catalyst material."},{question:"Why did it return after replacement?",answer:"An upstream cause, leak, wrong application or sensor fault may remain."},{question:"What proves repair?",answer:"Healthy upstream operation and a completed catalyst monitor without pending P0420."}],deepDive:[{heading:"Use the 2010 rattle bulletin exactly as written",paragraphs:["Toyota's procedure has the technician increase engine speed and localize the noise to the catalyst section while observing hot-exhaust safety. The replacement branch follows only when that rattle is loudest at the specified section.","A quiet 2010 truck or any unmatched year/engine returns to normal P0420 diagnosis. The presence of the code alone does not satisfy the bulletin."]},{heading:"Towing history can reveal the upstream cause",paragraphs:["Ask whether the lamp flashed, power dropped or fuel economy changed while towing or climbing. High load exposes weak ignition and fuel-control faults that can overheat the converter.","Review permanent and historical codes before clearing. A normal unloaded idle after the trip cannot prove the catalyst was never exposed to raw fuel."]},{heading:"Parts must match the emissions label",paragraphs:["Use VIN and the underhood label to identify certification and the correct Bank 1 exhaust assembly. A physically fitting converter may lack the correct legal approval or monitor capacity.","Check emissions warranty and any VIN-specific program separately. A TSB, recall and warranty are not interchangeable."]}],sources:[catalyst2010,manuals]}),
article({slug:"p0171",code:"P0171",title:"P0171 Code Toyota Tacoma: Lean Bank 1 Diagnosis by Engine",description:"Diagnose Tacoma P0171 with idle/load fuel trims, intake and purge tests, exhaust inspection and measured fuel delivery for four-cylinder and V6 engines.",definition:"System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Avoid towing, steep climbs and hard acceleration until fuel delivery and misfire are checked. Stop for a flashing lamp, detonation, severe hesitation, overheating or stalling. A steady lamp on a smooth truck may allow a short diagnostic trip.",quickAnswer:"P0171 means Bank 1 fuel correction exceeded its calibrated lean limit. It does not say the A/F sensor failed. Compare Bank 1 with Bank 2 on V6 trucks and compare correction at idle versus higher airflow. Then smoke-test intake/PCV/booster plumbing, test purge sealing, inspect the Bank 1 exhaust ahead of the sensor, verify MAF/MAP plausibility and measure fuel delivery for the exact engine. Dusty intake leaks and aftermarket intake changes deserve explicit inspection on a Tacoma.",symptoms:[{key:"idle",label:"Correction strongest at idle",response:"Smoke-test intake, PCV and brake-booster paths."},{key:"load",label:"Lean worsens while towing or climbing",response:"Measure fuel pressure/volume and verify MAF response under safe load."},{key:"bank",label:"V6 Bank 1 only",response:"Inspect local gasket, injector and exhaust paths; compare Bank 2."},{key:"dust",label:"After filter or off-road service",response:"Check airbox sealing, duct cracks, clamps and MAF contamination."},{key:"refuel",label:"Rough after refueling",response:"Test purge for leakage when commanded closed."}],causes:[{cause:"Unmetered intake, PCV or booster air",evidence:"Trim highest at idle; smoke escapes",firstTest:"Regulated smoke test downstream of MAF"},{cause:"Low fuel pressure or injector delivery",evidence:"Trim rises with demand or misfire appears",firstTest:"Measure engine-specific pressure and contribution"},{cause:"Purge valve leaks into intake",evidence:"Post-refuel symptom or flow commanded off",firstTest:"Command and independent physical seal test"},{cause:"Bank 1 upstream exhaust leak",evidence:"Cold tick/soot with false lean response",firstTest:"Inspect cold and leak-test safely"},{cause:"MAF/A/F sensor bias or intake modification",evidence:"Physical/fuel checks pass and response fails",firstTest:"Restore known intake geometry and test circuits/PIDs"}],freezeFrame:["Bank 1 and Bank 2 trims where applicable","RPM, load, speed and coolant temperature","MAF, MAP and throttle angle","Fuel pressure or delivery evidence","Purge command/time since refuel","Filter, snorkel, intake and towing history"],steps:[{title:"Preserve the trim pattern",detail:"Record the stored state and both banks before clearing."},{title:"Identify engine and bank",detail:"Separate 2TR four-cylinder from 5VZ/1GR/2GR V6 and turbo engines."},{title:"Compare idle with airflow",detail:"Use the change to prioritize air leaks versus delivery."},{title:"Smoke-test and test purge",detail:"Include booster, PCV and modified intake joints."},{title:"Measure fuel and sensor response",detail:"Do not infer low pressure from the code."},{title:"Verify under the original safe condition",detail:"Confirm normal correction without pending return."}],dontReplace:"Do not replace the Bank 1 A/F sensor, MAF or fuel pump from P0171 alone. Establish the idle/load and bank pattern and prove the subsystem with a leak, pressure or response test.",yearNotes:["Inline-four Tacomas have only Bank 1; a V6 Bank-1-only P0171 points toward a local cause more than shared fuel supply.","1GR-FE and 2GR-FKS use different fuel and intake data, and 2024+ turbo engines add charge-pressure plumbing.","Snorkels, oiled filters and aftermarket intake tubes can alter metering or introduce leaks.","No broad Tacoma P0171 parts bulletin is cited; use current VIN-specific TIS."],faqs:[{question:"Does P0171 mean the oxygen sensor is bad?",answer:"No. The sensor may be correctly reporting a real lean mixture."},{question:"Can a vacuum leak cause it?",answer:"Yes, especially when correction is highest at idle."},{question:"Can a weak fuel pump cause it?",answer:"Yes, particularly when correction worsens with load; measure pressure first."},{question:"Which bank is Bank 1?",answer:"It is the bank containing cylinder 1; confirm the exact V6 layout."},{question:"Can a snorkel cause P0171?",answer:"A leak, sensor orientation or restriction in a modified intake can affect metering."},{question:"Can I tow with it?",answer:"Avoid heavy load until fuel delivery and misfire are checked."},{question:"Can purge cause it?",answer:"Unexpected purge flow can disturb idle fueling."},{question:"What proves repair?",answer:"Normal correction at idle and load with no pending P0171."}],deepDive:[{heading:"A truck-specific lean test includes dust and modifications",paragraphs:["Inspect the clean side of the airbox for dust tracks, seal damage and loose clips. Follow the duct to the throttle or turbo inlet, including snorkel adapters and any ports added for accessories.","Cleaning a MAF cannot seal a cracked hose. Photograph modifications and restore known geometry when possible before judging sensor calibration."]},{heading:"Bank comparison prevents a wrong fuel-pump diagnosis",paragraphs:["On a V6, similar positive correction on both banks supports shared air metering or fuel supply. Bank 1 alone shifts attention toward its gasket, injectors and upstream exhaust.","Compare at the same rpm/load and label units. Bank-to-bank differences during transient acceleration are less useful than stable matched states."]},{heading:"Verify with the same kind of load—safely",paragraphs:["If the code set towing, use recorded load and pressure data to plan a controlled test; do not recreate maximum grade/load before confirming fuel delivery.","After repair, check pending codes and trims under a safe representative condition. A good driveway idle does not close a load-dependent lean fault."]}],sources:[manuals]}),
article({slug:"p0441",code:"P0441",title:"P0441 Code Toyota Tacoma: EVAP Purge-Flow Diagnosis",description:"Diagnose Tacoma P0441 with original cap evidence, purge/vent commands, tank-pressure data and regulated smoke—including off-road line damage.",definition:"Evaporative Emission Control System Incorrect Purge Flow",severity:"Service soon",driveAdvice:"P0441 alone usually permits short-term driving. Stop for liquid fuel, strong vapor odor, stalling or severe post-refuel hard starting. EVAP work involves fuel vapor; avoid flames, sparks and unrestricted shop air.",quickAnswer:"P0441 means the ECM commanded an EVAP purge test but did not see the expected flow or tank-pressure response. It does not automatically name a purge valve. A cap/filler leak, purge VSV that leaks or cannot flow, vent fault, restricted or crushed vapor line, canister contamination, tank-pressure bias or hose-routing error can all cause it. On a Tacoma, inspect underbody lines and canister/vent exposure after mud, water, impact or frame/tank work.",symptoms:[{key:"refuel",label:"Hard start after refueling",response:"Test purge physical sealing into the intake while commanded off."},{key:"odor",label:"Vapor smell near rear of truck",response:"Inspect canister, filler and tank-area lines promptly."},{key:"offroad",label:"Code after off-road or mud use",response:"Check vent filter/valve and exposed vapor lines for blockage or damage."},{key:"repair",label:"After tank/frame work",response:"Compare every hose/quick-connect with the VIN-correct routing."},{key:"click",label:"Valve clicks",response:"Movement does not prove correct flow or sealing."}],causes:[{cause:"Purge VSV leaks, restricts or has circuit fault",evidence:"Command and physical flow/seal disagree",firstTest:"Bidirectional command plus independent seal/flow test"},{cause:"Vent/closed valve or filter blocked/damaged",evidence:"Pressure response wrong after mud/water exposure",firstTest:"Inspect and command vent path"},{cause:"Cap, filler or vapor-system leak",evidence:"Seal damage or regulated smoke escape",firstTest:"Document cap then low-pressure smoke-test"},{cause:"Crushed, disconnected or misrouted line",evidence:"Off-road impact or recent tank/frame service",firstTest:"Full routing inspection and controlled flow test"},{cause:"Saturated canister or pressure-sensor bias",evidence:"Topping-off/liquid fuel or implausible PID",firstTest:"Inspect canister and controlled sensor response"}],freezeFrame:["Fuel level and time since refueling","Purge/vent commands and tank pressure","Ambient/coolant temperature and soak","Companion EVAP codes","Off-road, water, impact and repair history","Cap/filler original condition"],steps:[{title:"Preserve cap and freeze frame",detail:"Record the original condition before tightening or clearing."},{title:"Map the exact EVAP layout",detail:"Identify tank, canister, purge, vent and pressure/leak-detection hardware."},{title:"Inspect exposed truck routing",detail:"Check frame/tank-area lines, vent and clips for damage/blockage."},{title:"Test commands and physical sealing",detail:"Separate electrical clicking from actual vapor control."},{title:"Smoke at regulated pressure",detail:"Inspect every quick-connect and seam without shop air."},{title:"Run the monitor correctly",detail:"Meet fuel-level/soak conditions and check pending status."}],dontReplace:"Do not replace the purge valve because the code includes 'purge flow.' A Tacoma vent path packed with debris or a damaged frame-side vapor line can create the same failed system response.",yearNotes:["Tacoma EVAP hardware and routing change across generations, wheelbases and engine/fuel-tank configurations.","Mud, water and off-road impacts add vent/filter and underbody-line failure modes less common on passenger cars.","After tank, frame or bed work, misrouted or incompletely seated quick-connects deserve priority.","No unrelated Mazda/Volkswagen P0441 bulletin is used as Tacoma evidence."],faqs:[{question:"Is P0441 always the purge valve?",answer:"No. It is an incorrect system-flow response."},{question:"Can the gas cap cause it?",answer:"A cap/filler leak can influence some monitor strategies, but must be tested."},{question:"Can mud cause P0441?",answer:"Debris or water can restrict/damage exposed vent components."},{question:"Why hard start after filling?",answer:"A leaking purge valve can flood the intake with vapor."},{question:"Does clicking prove a valve good?",answer:"No. It must seal and flow correctly."},{question:"Can I drive?",answer:"Usually briefly if alone; stop for fuel leakage, odor or stalling."},{question:"How is it verified?",answer:"With commands, pressure response, routing inspection and regulated smoke."},{question:"What proves repair?",answer:"Correct EVAP response and a completed monitor without pending P0441."}],deepDive:[{heading:"Inspect the Tacoma from the tank forward",paragraphs:["Follow the filler and vapor plumbing around the tank, frame and canister before focusing only under the hood. Look for missing clips, abrasion, crushed sections and mud-packed vent hardware.","Photograph routing after recent bed, tank or frame service. A hose on the wrong port can look electrically normal while the monitor response remains wrong."]},{heading:"Commanded state and actual vapor control are separate",paragraphs:["A scan tool can show the ECM command, but the valve may still leak, stick or lack flow. Test physical sealing/flow and circuit operation as two separate facts.","Watch tank-pressure response while controlling the other paths. That response is more useful than replacing multiple valves because one clicks differently."]},{heading:"Use only EVAP-regulated smoke",paragraphs:["Unrestricted shop air can damage the canister, sensor or tank. Use approved equipment and Toyota's pressure limit.","After the physical repair, wait for correct fuel level and soak. Clearing the lamp does not prove the purge-flow monitor can pass."]}],sources:[manuals]}),
article({slug:"p0455",code:"P0455",title:"P0455 Code Toyota Tacoma: Large EVAP Leak and Underbody Inspection",description:"Find Tacoma P0455 with cap/filler checks, valve sealing, regulated smoke and inspection of exposed tank, canister and frame-side vapor lines.",definition:"Evaporative Emission System Leak Detected (Gross Leak/No Flow)",severity:"Service soon",driveAdvice:"P0455 alone generally allows a short trip, but stop for visible liquid fuel, strong vapor odor, stalling or severe post-refuel trouble. Inspect after underbody impact before driving over hot terrain or near ignition sources.",quickAnswer:"P0455 means the EVAP monitor could not create or retain expected pressure/vacuum and interpreted the failure as a gross leak or no flow. A loose cap, disconnected hose, purge or vent valve held open, cracked canister, filler/tank seal, pressure-sensor bias or blockage can cause it. Tacoma underbody exposure makes frame-side lines, tank quick-connects and canister/vent damage especially important after off-road impact or service.",symptoms:[{key:"cap",label:"Code after refueling",response:"Document cap engagement, seal and filler condition before clearing."},{key:"impact",label:"After trail/underbody impact",response:"Inspect tank shield area, canister and frame-side vapor lines."},{key:"odor",label:"Strong vapor smell",response:"Stop and inspect promptly for liquid or vapor leakage."},{key:"stall",label:"Hard start after filling",response:"Test purge for physical leakage when commanded closed."},{key:"other",label:"P0441/vent code also set",response:"Diagnose valve sequence and pressure response together."}],causes:[{cause:"Loose, wrong or damaged fuel cap/filler seal",evidence:"Original state or visible seal damage",firstTest:"Document and verify correct cap/filler"},{cause:"Disconnected/cracked underbody vapor line",evidence:"Impact/service history or smoke leakage",firstTest:"Inspect routing then regulated smoke"},{cause:"Purge or vent valve cannot seal",evidence:"Flow remains despite closed command",firstTest:"Command and independent sealing tests"},{cause:"Canister, tank or pump-module seal damage",evidence:"Smoke at seam or impact/liquid contamination",firstTest:"Isolate exact tank configuration"},{cause:"Pressure sensor bias or blocked test path",evidence:"Implausible response or no expected flow",firstTest:"Controlled response and line-flow test"}],freezeFrame:["Fuel level, ambient temperature and soak","Tank-pressure data and valve commands","Time since refueling","Off-road/impact/towing and tank-service history","Companion EVAP codes","Cap and filler original condition"],steps:[{title:"Keep original evidence",detail:"Record cap state, fuel level and companion codes."},{title:"Inspect exposed truck hardware",detail:"Check tank, filler, frame lines, canister and vent."},{title:"Identify the generation layout",detail:"Use VIN/engine/wheelbase routing."},{title:"Control purge and vent",detail:"Test electrical command and physical sealing separately."},{title:"Smoke at regulated pressure",detail:"Localize every quick-connect, hose and seam."},{title:"Complete the monitor",detail:"Meet enable conditions and check pending P0455."}],dontReplace:"Do not repeatedly fit caps or replace the canister without localization. A disconnected frame-side hose or valve held open can look identical to a 'large leak' monitor.",yearNotes:["Wheelbase, engine and generation can change tank/canister routing and component access.","Off-road damage, rodents, corrosion repairs and tank removal add Tacoma-specific history clues.","Large leak describes monitor magnitude; an electrically commanded valve that stays open may be the opening.","No broad Tacoma P0455 parts bulletin is cited."],faqs:[{question:"Is P0455 always a gas cap?",answer:"No. Hoses, valves, canister and tank/filler seals can cause it."},{question:"Can off-road damage cause it?",answer:"Yes, exposed vapor lines or canister hardware can be damaged."},{question:"Can I drive?",answer:"Usually briefly if alone; not with liquid fuel or strong odor."},{question:"Can purge cause it?",answer:"Yes, if the valve cannot seal during the monitor."},{question:"How is the leak found?",answer:"With underbody inspection, valve commands, pressure data and regulated smoke."},{question:"Why did a new cap not fix it?",answer:"The cap may not be the cause or another leak remains."},{question:"Can topping off matter?",answer:"Liquid fuel can saturate the charcoal canister."},{question:"What proves repair?",answer:"The EVAP system seals and completes its monitor without pending P0455."}],deepDive:[{heading:"Start with the truck's recent underbody history",paragraphs:["Ask about rock strikes, recovery points, bed removal, frame work, fuel-pump service and rodent exposure. These clues can take the inspection directly to a disturbed hose or connector.","Do not lower the tank before inspecting accessible frame runs and canister connections. Smoke may reveal the path without major disassembly."]},{heading:"Gross leak can be a valve, not a hole",paragraphs:["Control purge and vent while observing tank-pressure response. A valve that clicks but cannot seal presents a large opening to the monitor.","Test circuits and physical sealing independently so electrical activity is not mistaken for vapor control."]},{heading:"Safety inspection and monitor verification are both required",paragraphs:["A passing monitor does not excuse a visible liquid-fuel leak, and an odor complaint should not wait solely for readiness. Address physical safety first.","After repair, allow the proper soak and fuel-level window. Repeated code clearing delays the very monitor needed to close the job."]}],sources:[manuals]}),
article({slug:"p0300",code:"P0300",title:"P0300 Code Toyota Tacoma: Misfire Diagnosis and 2TR-FE Recall Check",description:"Diagnose Tacoma P0300 using cylinder patterns, ignition, fuel and compression tests plus exact 2013–2014 2TR-FE valve-spring recall boundaries.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"A flashing lamp means active catalyst-damaging misfire. Release the throttle, stop towing or climbing and pull over safely. Stop outright for severe shaking, raw-fuel odor, valvetrain noise, overheating or loss of oil pressure.",quickAnswer:"P0300 means crankshaft-speed variation indicates random/multiple misfire or no single cylinder dominates. It does not mean every coil failed. Save cylinder subcodes/counters and freeze frame, then separate fixed-cylinder, bank-specific and whole-engine patterns. For certain VIN-identified 2013–2014 2TR-FE Tacomas, Toyota Safety Recall D0U addresses valve springs that may break and cause abnormal noise, rough running or engine stoppage; verify VIN status rather than assuming coverage.",symptoms:[{key:"flash",label:"Lamp flashes under load/tow",response:"Stop load immediately to protect the catalyst."},{key:"noise",label:"Rough running with valvetrain noise",response:"Shut down and inspect mechanical valve motion/compression; check D0U eligibility on matched trucks."},{key:"one",label:"One cylinder dominates",response:"Use one controlled coil/plug test, then injector and compression evidence."},{key:"bank",label:"One V6 bank dominates",response:"Inspect that bank's air, injectors, harness, exhaust and timing."},{key:"dust",label:"After dusty/off-road use",response:"Inspect intake sealing, airbox clean side and MAF before sensor replacement."}],causes:[{cause:"Plug, coil, boot or connector fault",evidence:"Counter follows a controlled swap",firstTest:"Inspect plugs in order and move one known-good coil"},{cause:"Injector or fuel-delivery fault",evidence:"Ignition passes; contribution/pressure fails",firstTest:"Engine-specific injector and pressure tests"},{cause:"Intake leak, dust ingress or purge fault",evidence:"Fuel-trim/smoke/refuel evidence",firstTest:"Inspect clean-air path, smoke-test and test purge"},{cause:"Compression, valve spring or other mechanical fault",evidence:"Fixed cylinder, noise or leakage result",firstTest:"Relative compression, leak-down and valve-motion checks"},{cause:"VVT/timing or shared voltage problem",evidence:"Correlation/circuit codes or multiple cylinders",firstTest:"Cam data, mechanical timing and voltage-drop tests"}],freezeFrame:["Cylinder-specific subcodes and counters","RPM, load, coolant temperature and speed","Fuel trims and commanded/actual pressure","Cam/VVT and circuit companion codes","Towing, fuel and off-road history","Engine code, VIN recall status and recent repair"],steps:[{title:"Stop damaging operation",detail:"Do not reproduce a flashing-lamp misfire under tow."},{title:"Preserve and classify counters",detail:"Separate cylinder, bank and system patterns."},{title:"Test ignition one change at a time",detail:"Read plugs and control swaps."},{title:"Inspect air and fuel",detail:"Check dust paths, purge, pressure and injector contribution."},{title:"Measure mechanical condition",detail:"Use compression/leak-down and check matched recall history."},{title:"Verify under a safe representative condition",detail:"Confirm stable counts and no pending return."}],dontReplace:"Do not install all coils or diagnose a valve spring from P0300 alone. D0U applies only to certain 2013–2014 2TR-FE VINs; verify eligibility and mechanical evidence.",yearNotes:["Safety Recall D0U covers certain 2013–2014 Tacoma 2TR-FE vehicles; pitted valve springs may break and cause noise, rough performance or engine stoppage.","Recall completion/eligibility must be checked by VIN with Toyota/NHTSA.","Four-cylinder and V6 cylinder/bank layouts differ, as do 2GR direct/port injection and 2024+ turbo fuel systems.","Towing and steep grades expose ignition/fuel faults that may not appear at idle."],faqs:[{question:"Does P0300 mean all coils are bad?",answer:"No. Air, fuel, injector, compression, timing and voltage faults can cause it."},{question:"Can I drive?",answer:"Stop for a flashing lamp, severe shaking or mechanical noise."},{question:"Is there a Tacoma valve-spring recall?",answer:"Yes, for certain VIN-identified 2013–2014 2TR-FE trucks."},{question:"Does every 2013–2014 Tacoma qualify?",answer:"No. Engine and VIN eligibility must match."},{question:"How do I find the cylinder?",answer:"Use P0301-series codes, counters and controlled tests."},{question:"Can low fuel pressure cause it?",answer:"Yes, especially when counts rise with load."},{question:"Should I clear the code first?",answer:"No. Save freeze frame and counters."},{question:"What proves repair?",answer:"Stable cylinder counts and no pending misfire in the original safe state."}],deepDive:[{heading:"A towing misfire needs load evidence without repeated damage",paragraphs:["Save the original load, rpm and fuel-pressure data. Reproduce only enough safe demand to confirm the repaired system; do not pull the same grade with a flashing lamp.","Weak ignition and low fuel delivery may pass a driveway idle. That does not justify replacing every coil; identify which counters and pressures change first."]},{heading:"How D0U fits a P0300 diagnosis",paragraphs:["The recall describes a supplier-related valve-spring pitting condition on certain 2TR-FE vehicles. Broken springs can create noise, rough running and loss of engine operation, all of which can accompany misfire.","Check VIN campaign status and measure valve motion/compression. A stored P0300 on an ineligible or quiet/compression-healthy truck is not proof of the recall condition."]},{heading:"Dust tracks are physical evidence",paragraphs:["Inspect the clean side of the filter housing and downstream duct for dust trails after off-road use. Unmetered or contaminated airflow can disturb multiple cylinders and fuel trims.","After correction, verify counters during the same cold/load class safely and inspect pending codes. A cleared lamp at idle is not enough."]}],sources:[valveRecall,manuals]}),
article({slug:"p0016",code:"P0016",title:"P0016 Code Toyota Tacoma: Cam-Crank Correlation and VVT Tests",description:"Diagnose Tacoma P0016 with oil and VVT checks, synchronized waveforms and mechanical timing for 2TR, 1GR, 2GR and turbo engines.",definition:"Crankshaft Position–Camshaft Position Correlation (Bank 1, Sensor A)",severity:"Stop soon",driveAdvice:"Minimize driving until oil pressure, timing noise and starting behavior are checked. Stop for persistent chain/phaser rattle, hard starting, stalling or low-oil-pressure warning. Do not tow or repeatedly rev an engine that may be mechanically out of time.",quickAnswer:"P0016 means the Bank 1 intake-cam signal is outside its expected relationship to the crankshaft. It identifies a relationship, not a failed cam sensor. Verify oil level/grade/pressure, compare desired and actual VVT angle, test oil-control and sensor circuits, inspect synchronized cam/crank waveforms and verify mechanical timing. Tacoma 2TR-FE, 1GR-FE, 2GR-FKS and T24A-FTS procedures are different.",symptoms:[{key:"noise",label:"Startup rattle",response:"Stop repeated starts and verify oil pressure plus timing hardware."},{key:"after",label:"After engine/timing work",response:"Recheck indexing, reluctors, connectors, grounds and learning."},{key:"oil",label:"Wrong or low oil",response:"Correct it and test VVT response; do not assume it repairs mechanical timing."},{key:"multi",label:"Multiple correlation codes",response:"Look for common oil, crank-signal, voltage or installation faults."},{key:"tow",label:"Power loss under load",response:"Avoid towing until physical timing integrity is proven."}],causes:[{cause:"Incorrect mechanical timing or worn chain components",evidence:"Stable offset, noise or repair history",firstTest:"Verify timing using the exact engine procedure"},{cause:"Low, aerated, dirty or wrong oil",evidence:"Level/specification/pressure abnormal",firstTest:"Verify oil and mechanical pressure"},{cause:"VVT oil-control valve or actuator fault",evidence:"Desired and actual angle do not track",firstTest:"Command VVT and test circuit/oil feed"},{cause:"Cam/crank sensor, wiring or reluctor fault",evidence:"Dropout, circuit code or abnormal waveform",firstTest:"Load-test circuits and scope synchronized signals"},{cause:"Calibration, learning or repair setup issue",evidence:"Fault began after ECM/engine service",firstTest:"Audit installation and required initialization"}],freezeFrame:["Desired/actual Bank 1 intake-cam angle","RPM/load and crank-versus-run setting state","Oil level, grade, temperature and pressure","VVT/cam/crank companion codes","Cranking battery voltage","Recent timing, head or engine work"],steps:[{title:"Check noise and oil first",detail:"Do not repeatedly operate a noisy engine."},{title:"Identify engine and Bank 1",detail:"Select the correct four-cylinder, V6 or turbo procedure."},{title:"Graph VVT command",detail:"Compare desired and actual intake angle."},{title:"Test oil control and wiring",detail:"Verify circuits and oil feed before parts."},{title:"Scope correlation and verify timing",detail:"Separate dropout from mechanical offset."},{title:"Initialize and verify",detail:"Complete required learning and repeat the safe setting state."}],dontReplace:"Do not replace cam and crank sensors as a pair from P0016. A new sensor cannot fix low oil pressure, a phaser/actuator fault, damaged reluctor or incorrect chain timing.",yearNotes:["2TR-FE, 1GR-FE, 2GR-FKS and T24A-FTS use different timing drives, VVT strategies and service tools.","On V6 engines, Bank 1 contains cylinder 1; use the engine-specific diagram rather than guessing by truck side.","Recent chain/head/engine work changes priority toward installation and learned values.","No broad Tacoma P0016 parts bulletin is cited."],faqs:[{question:"Is P0016 a bad cam sensor?",answer:"Not necessarily; it is a cam-to-crank relationship fault."},{question:"Which cam is Sensor A?",answer:"Normally the Bank 1 intake cam; confirm the exact engine manual."},{question:"Can wrong oil cause it?",answer:"It can disrupt VVT control but not every correlation fault."},{question:"Can I tow?",answer:"No heavy towing until oil pressure and timing integrity are checked."},{question:"Can a stretched chain cause it?",answer:"Yes, as can actuator, reluctor and installation faults."},{question:"Why after repair?",answer:"Timing, connector placement or initialization may be wrong."},{question:"Should both sensors be replaced?",answer:"No. Test circuits and waveforms first."},{question:"What proves repair?",answer:"Correct desired/actual angle and no pending correlation code."}],deepDive:[{heading:"Correlation needs two signals and one mechanical check",paragraphs:["A disappearing waveform points toward electrical/reluctor integrity; two clean signals with a stable offset point toward actuator or mechanical timing. Capture both before disassembly.","Use known-good waveform information for the exact engine. Tooth counts and reference positions are not portable between generations."]},{heading:"Oil control comes before timing-cover removal",paragraphs:["Confirm level, viscosity, pressure and VVT command/response. Sludge or restricted control passages can prevent the cam from reaching its expected position.","If the cam stays offset, noise persists or repair history fits, move to mechanical verification with Toyota procedures."]},{heading:"Verification must include load class without abuse",paragraphs:["Repeat the safe rpm/temperature state from freeze frame but do not tow with unresolved correlation. Watch desired/actual angle and pending codes.","A quiet idle after clearing is insufficient when the code set during acceleration or startup."]}],sources:[manuals]}),
article({slug:"p0128",code:"P0128",title:"P0128 Code Toyota Tacoma: Thermostat and Coolant Warm-Up Diagnosis",description:"Diagnose Tacoma P0128 using cold-soak sensor comparison, coolant and thermostat checks, warm-up graphs and fan operation by engine.",definition:"Coolant Temperature Below Thermostat Regulating Temperature",severity:"Service soon",driveAdvice:"Usually safe for a short diagnostic trip if coolant level is correct and temperature remains stable. Stop for steam, visible leakage, red temperature warning, rapid gauge change or loss of heater output with low coolant. Never remove a hot pressure cap.",quickAnswer:"P0128 means coolant did not warm as quickly or reach the range expected by the ECM. A thermostat leaking open is common, but the code does not prove it. Check coolant cold, compare ECT and IAT with ambient after an overnight soak, graph warm-up, observe radiator-hose and fan behavior and test the ECT circuit. Engine family, ambient temperature, heater load and towing history matter.",symptoms:[{key:"slow",label:"Slow heater/gauge warm-up",response:"Graph ECT from true cold start and observe radiator flow."},{key:"normal",label:"Gauge appears normal",response:"The dash display is damped; use scan data and monitor criteria."},{key:"after",label:"After coolant service",response:"Check fill/bleed, thermostat orientation and connector disturbance."},{key:"cold",label:"ECT wrong before startup",response:"Compare ECT/IAT with measured ambient."},{key:"fan",label:"Fan runs on a cold engine",response:"Check command, relays and companion inputs."}],causes:[{cause:"Thermostat leaks or is stuck open",evidence:"Slow rise and premature radiator heat",firstTest:"Cold-start ECT graph and thermal observation"},{cause:"Low coolant, trapped air or leak",evidence:"Low level, heater change or recent work",firstTest:"Cold level, pressure/leak and bleed check"},{cause:"ECT sensor or circuit biased cold",evidence:"Cold ECT disagrees with IAT/ambient",firstTest:"Cold-soak plausibility and circuit test"},{cause:"Cooling fan runs unnecessarily",evidence:"Fan operates cold without valid request",firstTest:"Compare command with output"},{cause:"Wrong thermostat/application or calibration",evidence:"Repair history or physical tests pass",firstTest:"Verify VIN part and current Toyota TIS"}],freezeFrame:["ECT/IAT and ambient after soak","RPM, speed, load and warm-up time","Cooling-fan command and operation","Heater and radiator-hose behavior","Coolant-service/leak history","Ambient, towing and grille modification history"],steps:[{title:"Inspect coolant cold",detail:"Check level and leaks safely."},{title:"Compare cold sensors",detail:"ECT/IAT should be plausible near ambient."},{title:"Graph full warm-up",detail:"Watch rise, thermostat opening and fans."},{title:"Separate sensor from hardware",detail:"Compare actual temperature with scan data."},{title:"Verify part and bleeding",detail:"Use exact engine application."},{title:"Repeat a cold start",detail:"Confirm normal warm-up and no pending P0128."}],dontReplace:"Do not fit a thermostat from the code alone or import the Camry-only P0128 calibration bulletin. Prove actual Tacoma warm-up, coolant condition and ECT accuracy.",yearNotes:["Toyota T-SB-0045-13 commonly found in searches lists Camry, not Tacoma.","2TR, 1GR, 2GR and turbo engines use different thermostats, bleed procedures and specifications.","Cold ambient, heater demand and grille accessories can affect warm-up context but do not replace testing.","2024+ hybrid/turbo cooling includes additional circuits requiring correct identification."],faqs:[{question:"Does P0128 always mean thermostat?",answer:"No. Coolant, sensor bias and fan operation can cause slow measured warm-up."},{question:"Can I drive?",answer:"Usually briefly if level and temperature are stable; stop for overheating/leakage."},{question:"Why is cabin heat weak?",answer:"A leaking thermostat, low coolant or air can reduce heat."},{question:"Can the gauge look normal?",answer:"Yes; scan data are more precise than the damped gauge."},{question:"Does the Camry bulletin apply?",answer:"No. Its applicability does not list Tacoma."},{question:"Can cold weather alone set it?",answer:"Monitor calibration considers conditions; test thermostat and sensors."},{question:"Can a bad ECT sensor cause it?",answer:"Yes, if it reports colder than actual."},{question:"What proves repair?",answer:"A normal cold warm-up and passing monitor."}],deepDive:[{heading:"A true cold soak is essential",paragraphs:["Before startup, ECT and IAT should be plausible near measured ambient. Residual heat after a short stop makes this comparison misleading.","Record both before touching the thermostat. A biased ECT can mimic slow warming even when coolant flow is normal."]},{heading:"Truck accessories can change observations",paragraphs:["Heavy heater use, winter grille covers, auxiliary fans or front-mounted equipment can affect airflow/warm-up context. Document modifications and fan commands.","They do not automatically cause P0128; actual coolant and sensor behavior still decide the diagnosis."]},{heading:"Verify on another comparable cold start",paragraphs:["After repair, repeat the graph from cold and check pending codes. A warm restart cannot validate the original monitor.","Inspect leaks and coolant level again after heat cycles, especially following thermostat work."]}],sources:[manuals]}),
article({slug:"p1604",code:"P1604",title:"P1604 Code Toyota Tacoma: Startability Malfunction Diagnosis",description:"Diagnose Tacoma P1604 from failed-start evidence: cranking voltage, fuel, authorization, ignition, airflow, synchronization and compression.",definition:"Startability Malfunction",severity:"Diagnose promptly",driveAdvice:"If the truck starts and runs normally now, drive only as needed for diagnosis and avoid remote/off-road isolation. Stop repeated cranking when battery speed falls, cables heat, fuel odor grows or mechanical noise appears. Tow a no-start or repeatedly stalling truck.",quickAnswer:"P1604 means the ECM judged that the engine failed to start normally; it is an outcome code, not a starter or fuel-pump verdict. Reconstruct slow crank, normal-speed no-fire or start-then-stall. Test battery/cranking voltage and speed, cam/crank synchronization, immobilizer authorization, actual fuel/pressure, ignition, MAF/throttle/purge and compression. Toyota flex-fuel P1604 bulletins for Tundra/Sequoia do not list Tacoma.",symptoms:[{key:"slow",label:"Slow cranking",response:"Test battery and voltage drop at starter/grounds."},{key:"nofire",label:"Normal crank, no fire",response:"Check rpm/sync, authorization, fuel and ignition."},{key:"stall",label:"Starts then stalls",response:"Inspect immobilizer, airflow/throttle, purge and fuel continuity."},{key:"hot",label:"Only fails hot",response:"Capture hot sensor, pressure and crank-speed data before cooling."},{key:"remote",label:"After key/remote-start work",response:"Verify authorization and accessory wiring without bypassing security."}],causes:[{cause:"Weak battery, starter or cable voltage drop",evidence:"Low cranking speed/voltage or hot connection",firstTest:"Battery load and cranking voltage-drop tests"},{cause:"Fuel quantity/quality/pressure or injector fault",evidence:"No/low pressure or contaminated fuel",firstTest:"Verify actual fuel and engine-specific delivery"},{cause:"Crank/cam signal, ignition or immobilizer fault",evidence:"No rpm/sync/spark or authorization abnormal",firstTest:"Companion codes and start-authority data"},{cause:"Airflow, throttle or purge flooding",evidence:"Post-refuel stall or implausible intake data",firstTest:"Inspect air path and purge sealing"},{cause:"Compression or mechanical timing fault",evidence:"Uneven cranking, noise or correlation code",firstTest:"Relative compression and timing checks"}],freezeFrame:["Minimum cranking voltage and rpm","Cam/crank synchronization","Start authorization/immobilizer status","Fuel level, pressure and injector command","MAF/MAP/throttle and purge data","Hot/cold, remote-start and recent service history"],steps:[{title:"Name the start pattern",detail:"Record slow crank, no-fire or start-then-stall."},{title:"Save all codes",detail:"Companion codes outrank the outcome code."},{title:"Measure cranking quality",detail:"Test voltage, speed and cable drop."},{title:"Verify sync and authorization",detail:"Confirm ECM receives required signals."},{title:"Test fuel, ignition, air and compression",detail:"Follow the missing prerequisite."},{title:"Verify hot and cold starts",detail:"Confirm normal duration with no pending P1604."}],dontReplace:"Do not replace the starter, fuel pump or ECM from P1604 alone. Tundra/Sequoia alcohol-density bulletins do not apply to Tacoma merely because the code matches.",yearNotes:["P1604 is Toyota-enhanced; Toyota-capable data may expose start-history detail absent from basic readers.","T-SB-0166-19 and predecessor list flex-fuel Tundra/Sequoia, not Tacoma.","Remote-start/security additions and off-road battery accessories can alter cranking/authorization and should be disclosed.","2024+ turbo/hybrid starting and fuel systems require their own procedures."],faqs:[{question:"What does P1604 mean?",answer:"The ECM detected abnormal or unsuccessful starting performance."},{question:"Is the starter bad?",answer:"Not automatically; many prerequisites can be missing."},{question:"Can a weak battery set it?",answer:"Yes, through inadequate cranking voltage or speed."},{question:"Can running out of fuel set it?",answer:"A failed start from insufficient fuel can contribute."},{question:"Do Tundra bulletins apply?",answer:"No, not unless Tacoma is listed—which those flex-fuel bulletins do not."},{question:"Can remote start matter?",answer:"Accessory wiring or authorization issues can change starting behavior."},{question:"Should I clear it first?",answer:"No. Save failed-start data and companion codes."},{question:"What proves repair?",answer:"Reliable hot/cold starts and no pending return."}],deepDive:[{heading:"Startability is an outcome, not a component",paragraphs:["Slow cranking prioritizes the battery/starter path. Normal cranking without firing prioritizes synchronization, authorization, fuel and ignition. Starting then stalling moves purge, throttle and security higher.","Write the pattern and temperatures down before charging the battery or cooling the engine."]},{heading:"Truck electrical modifications matter",paragraphs:["Winches, dual-battery systems, grounds, remote start and auxiliary wiring can introduce voltage drop or authorization problems. Inspect changes without assuming they are guilty.","Measure voltage at the relevant component during the event; an open-circuit battery reading cannot prove cranking performance."]},{heading:"Reject the wrong flex-fuel bulletin",paragraphs:["Search results may pair P1604 with Tundra/Sequoia alcohol-density calibration. Applicability is part of the evidence, and Tacoma is not listed.","Use VIN-correct Tacoma TIS and actual failed-start data. Similar code numbers do not make models interchangeable."]}],sources:[manuals]}),
article({slug:"p0101",code:"P0101",title:"P0101 Code Toyota Tacoma: MAF Performance and Intake Diagnosis",description:"Diagnose Tacoma P0101 through airbox, snorkel and duct inspection, smoke testing, sensor cross-checks and engine-breathing tests.",definition:"Mass or Volume Air Flow Circuit Range/Performance",severity:"Diagnose promptly",driveAdvice:"Avoid hard acceleration and towing with hesitation, rich/lean operation or reduced power. Stop for stalling, flashing misfire, heavy smoke or overheating. A steady lamp with stable running may permit a short test trip.",quickAnswer:"P0101 means MAF-reported airflow did not agree with the ECM's model of rpm, throttle, pressure and load. It does not prove the MAF is dirty. Inspect the filter/airbox clean side, duct/clamps, snorkel or aftermarket intake and turbo charge path where applicable; smoke-test downstream leaks; compare MAF, MAP, throttle, load and trims; then test circuits. Dust, purge, VVT or mechanical breathing can create the mismatch.",symptoms:[{key:"dust",label:"After dusty trail use",response:"Inspect filter sealing and clean-side dust tracks."},{key:"mod",label:"After snorkel/intake work",response:"Check sensor orientation, joints, restriction and calibration compatibility."},{key:"idle",label:"Rough idle with lean trims",response:"Smoke-test metered-air, PCV and booster/purge paths."},{key:"load",label:"Power loss towing",response:"Graph airflow/pressure and inspect restriction without maximum-load testing."},{key:"bump",label:"Intermittent on rough roads",response:"Inspect pins, harness strain and grounds while graphing."}],causes:[{cause:"Loose/split intake or unmetered-air leak",evidence:"Smoke escape or idle trim pattern",firstTest:"Inspect and smoke-test downstream of MAF"},{cause:"Wrong/restricted filter or airbox sealing failure",evidence:"Dust track, recent service or restriction",firstTest:"Verify part, seating and clean side"},{cause:"Biased/contaminated MAF or circuit fault",evidence:"Controlled response/electrical test fails",firstTest:"Power, ground, signal and plausibility"},{cause:"MAP/throttle/purge input mismatch",evidence:"Companion codes or command disagreement",firstTest:"Cross-check sensors and purge sealing"},{cause:"VVT, compression or exhaust/turbo restriction",evidence:"Airflow abnormal after intake/circuits pass",firstTest:"Engine-breathing and pressure/backpressure tests"}],freezeFrame:["MAF units/value, rpm and load","MAP/barometric/boost and throttle","Fuel trims and companion codes","Filter, snorkel and intake modifications","Coolant/intake temperature and voltage","Towing, dust and water-exposure history"],steps:[{title:"Save simultaneous data",detail:"Record units and all airflow witnesses."},{title:"Inspect truck air path",detail:"Check filter, airbox, snorkel, duct and turbo path."},{title:"Smoke/pressure-test correctly",detail:"Include downstream PCV/booster joints."},{title:"Cross-check MAF/MAP/throttle",detail:"Use KOEO and warm operating states."},{title:"Test circuits and breathing",detail:"Proceed after physical checks."},{title:"Verify safe airflow range",detail:"Confirm agreement and no pending P0101."}],dontReplace:"Do not repeatedly clean or replace the MAF. A dust leak, snorkel joint, wrong filter, purge flow, sensor input or engine-breathing issue can make a healthy MAF fail plausibility.",yearNotes:["Expected airflow differs among 2TR, 1GR, 2GR and turbo T24A engines and with altitude/temperature.","Aftermarket oiled filters, snorkels and intake tubes can change metering or introduce leaks.","Turbo engines require correct separation of inlet and pressurized charge-path tests.","No broad Tacoma P0101 parts bulletin is cited."],faqs:[{question:"Does P0101 mean bad MAF?",answer:"No. It is an airflow plausibility code."},{question:"Can dust cause it?",answer:"Contamination or a poor airbox seal can affect metering."},{question:"Can a snorkel cause it?",answer:"Leaks, restriction or sensor geometry changes can contribute."},{question:"Should I clean the MAF?",answer:"Only safely after inspection; cleaning is not a wiring/leak test."},{question:"Can I tow?",answer:"Avoid heavy load until airflow and fueling are verified."},{question:"Can purge matter?",answer:"Unexpected vapor flow can disturb the airflow model."},{question:"What data should be graphed?",answer:"MAF, MAP/boost, throttle, load, rpm and trims."},{question:"What proves repair?",answer:"Plausible airflow in the original condition without pending P0101."}],deepDive:[{heading:"Dust tracks tell a story scan data cannot",paragraphs:["Inspect the clean side of the filter and housing seams. Dust past the seal points to a physical entry path and possible MAF contamination.","Correct the seal before cleaning or replacing a sensor, or the same environment will return."]},{heading:"Modified intake geometry needs a known baseline",paragraphs:["Snorkel bends, couplers and sensor housings can change restriction or flow profile. Check for leaks and compare with the intended design.","Physical fit is not proof that the MAF sampling location matches calibration."]},{heading:"Load verification should not recreate abuse",paragraphs:["Use freeze-frame load and graph data after basic checks; do not tow hard with reduced power or lean correction.","A stable driveway idle cannot close a fault that only appears at high airflow."]}],sources:[manuals]}),
article({slug:"p0138",code:"P0138",title:"P0138 Code Toyota Tacoma: Bank 1 Sensor 2 High-Voltage Diagnosis",description:"Diagnose Tacoma P0138 by confirming Bank 1 Sensor 2, testing downstream wiring/response and separating actual rich exhaust from sensor bias.",definition:"Oxygen Sensor Circuit High Voltage (Bank 1, Sensor 2)",severity:"Service soon",driveAdvice:"P0138 alone usually permits a short diagnostic trip. Stop for flashing misfire, raw-fuel odor, black smoke or an overheating catalyst. Actual rich operation can destroy the converter even when the code names a sensor circuit.",quickAnswer:"P0138 means Bank 1 downstream oxygen-sensor signal remained above the expected range or response. It does not prove the sensor or catalyst failed. Confirm Bank 1 Sensor 2 for the exact four-cylinder/V6 exhaust, test actual rich operation from fuel or purge, inspect exhaust and heat-damaged/crossed wiring, then perform controlled response and circuit tests. Toyota P0138 bulletins for Camry/RAV4 do not list Tacoma.",symptoms:[{key:"rich",label:"Black smoke or fuel odor",response:"Diagnose actual rich fueling before sensor replacement."},{key:"after",label:"After exhaust work",response:"Verify connector identity, routing and exhaust sealing."},{key:"fixed",label:"Signal high engine-off",response:"Test circuit short/bias before condemning the sensor."},{key:"codes",label:"Rich/purge codes also present",response:"Treat mixture control as an upstream influence."},{key:"alone",label:"No drive symptom",response:"Graph response and perform wiring tests under setting conditions."}],causes:[{cause:"Downstream O2 sensor internally biased",evidence:"Mixture/circuit/exhaust pass but response fails",firstTest:"Toyota-specified controlled response test"},{cause:"Signal wire shorted or heat damaged",evidence:"High signal persists during circuit isolation",firstTest:"Inspect routing and load-test signal/ground"},{cause:"Actual rich exhaust from fuel/injector fault",evidence:"Negative trims, smoke or rich codes",firstTest:"Fuel pressure and injector leakage tests"},{cause:"Purge valve feeding excessive vapor",evidence:"Post-refuel symptom or flow commanded off",firstTest:"Independent purge sealing test"},{cause:"Crossed connector or exhaust service error",evidence:"Recent sensor/exhaust work",firstTest:"Verify identity, pins and exhaust integrity"}],freezeFrame:["Bank 1 Sensor 2 signal","Upstream A/F sensor data","Fuel trims and rich/lean codes","RPM, load, coolant temperature and speed","Purge command/refueling history","Exhaust modification/repair and towing history"],steps:[{title:"Map Bank 1 Sensor 2",detail:"Use exact engine/exhaust layout."},{title:"Save mixture context",detail:"Record upstream data, trims and codes."},{title:"Inspect wiring and exhaust",detail:"Check heat, abrasion, crossed connectors and leaks."},{title:"Test actual rich operation",detail:"Evaluate fuel and purge."},{title:"Test circuit and sensor response",detail:"Use controlled Toyota procedure."},{title:"Verify original state",detail:"Confirm normal response and no pending P0138."}],dontReplace:"Do not replace Sensor 2, the catalyst or ECM from P0138. Prove mixture and circuit behavior. Toyota multi-model P0138 bulletins that list Camry/RAV4 do not include Tacoma.",yearNotes:["Four-cylinder Tacoma has only Bank 1; V6 Bank 1 contains cylinder 1 and must be mapped by engine diagram.","Sensor and connector locations differ across 2TR, 1GR, 2GR and turbo exhaust systems.","T-SB-0001-10 and T-SB-0151-18 do not list Tacoma in their applicability tables.","Aftermarket exhaust and sensor extensions can create routing or response problems."],faqs:[{question:"What is Bank 1 Sensor 2?",answer:"The downstream oxygen sensor after the Bank 1 catalyst."},{question:"Does P0138 mean bad sensor?",answer:"Not automatically; rich exhaust or wiring can hold it high."},{question:"Does it mean bad catalyst?",answer:"No. P0138 is not catalyst-efficiency code P0420."},{question:"Can injector leakage cause it?",answer:"Yes, through genuinely rich exhaust."},{question:"Can purge cause it?",answer:"Excess vapor can enrich the mixture."},{question:"Do RAV4/Camry bulletins apply?",answer:"No. Their applicability does not list Tacoma."},{question:"Can I drive?",answer:"Usually briefly if alone; stop for raw fuel, smoke or flashing misfire."},{question:"What proves repair?",answer:"Normal response, corrected mixture/circuit and no pending P0138."}],deepDive:[{heading:"Decide whether the exhaust is rich before blaming the sensor",paragraphs:["Negative trims, fuel odor, deposits and rich companion codes prioritize pressure, injectors and purge. Normal mixture evidence moves circuit and sensor response higher.","Use data rather than tailpipe appearance alone; off-road dust can discolor exhaust without proving rich operation."]},{heading:"Bank identification prevents a service-created fault",paragraphs:["On V6 trucks, verify the bank containing cylinder 1 and follow the harness to the downstream sensor. Exhaust work can cross or stretch connectors.","On four-cylinders there is one bank, but upstream and downstream connectors can still be confused."]},{heading:"Applicability tables block borrowed fixes",paragraphs:["Toyota's well-indexed P0138 bulletins cover other models. They are useful examples of disciplined testing, but their calibration/repair paths are not Tacoma authorization.","Document the Tacoma-specific failed test from current TIS and verify under the original operating state."]}],sources:[manuals]}),
];
